--
-- Name: blog; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.blog (
    id integer NOT NULL,
    title text,
    authors text,
    contents text,
    metadata jsonb
);


ALTER TABLE public.blog OWNER TO postgres;

--
-- Name: blog_contents_embeddings_store; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.blog_contents_embeddings_store (
    embedding_uuid uuid DEFAULT gen_random_uuid() NOT NULL,
    id integer NOT NULL,
    chunk_seq integer NOT NULL,
    chunk text NOT NULL,
    embedding public.vector(768) NOT NULL
);


ALTER TABLE public.blog_contents_embeddings_store OWNER TO postgres;

--
-- Name: blog_contents_embeddings; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.blog_contents_embeddings AS
 SELECT t.embedding_uuid,
    t.chunk_seq,
    t.chunk,
    t.embedding,
    t.id,
    s.title,
    s.authors,
    s.contents,
    s.metadata
   FROM (public.blog_contents_embeddings_store t
     LEFT JOIN public.blog s ON ((t.id = s.id)));


ALTER VIEW public.blog_contents_embeddings OWNER TO postgres;

--
-- Name: blog_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.blog_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.blog_id_seq OWNER TO postgres;

--
